// displayTitle names an episode with its show, e.g. "Cosmos · S1E3 · The Harmony of the Worlds".
func displayTitle(m store.Media) string {
	if m.CollectionName == "" {
		return m.Title
	}
	return fmt.Sprintf("%s · S%dE%d · %s", m.CollectionName, m.Season, m.Episode, m.Title)
}

